CREATE OR REPLACE FUNCTION public.sync_variant_total() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF pg_trigger_depth()>1 THEN RETURN NEW; END IF; UPDATE public.products SET stock=(SELECT coalesce(sum(stock),0) FROM public.product_variants WHERE code=NEW.code) WHERE code=NEW.code; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.rebalance_variants() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer; BEGIN IF pg_trigger_depth()>1 THEN RETURN NEW; END IF; SELECT count(*) INTO n FROM public.product_variants WHERE code=NEW.code; IF n>0 THEN IF NEW.stock=OLD.stock-1 THEN UPDATE public.product_variants SET stock=stock-1 WHERE code=NEW.code AND size=(SELECT size FROM public.product_variants WHERE code=NEW.code AND stock>0 ORDER BY stock DESC,size LIMIT 1); ELSE UPDATE public.product_variants v SET stock=NEW.stock/n+CASE WHEN (SELECT count(*) FROM public.product_variants z WHERE z.code=v.code AND z.size<=v.size)<=NEW.stock%n THEN 1 ELSE 0 END WHERE v.code=NEW.code; END IF; END IF; RETURN NEW; END $$;
DO $repair$ DECLARE def text; BEGIN SELECT pg_get_functiondef('public.place_order(jsonb,text,jsonb,boolean,boolean,jsonb)'::regprocedure) INTO def; def:=replace(def,'END $function$','EXCEPTION WHEN raise_exception THEN IF jsonb_array_length(short)>0 THEN RETURN jsonb_build_object(''ok'',false,''short'',short); END IF; RAISE; END $function$'); EXECUTE def; END $repair$;
CREATE OR REPLACE FUNCTION public.place_order(p_items jsonb,p_email text,p_shipping jsonb,p_kicked boolean) RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ SELECT public.place_order(p_items,p_email,p_shipping,p_kicked,false,'{}'::jsonb) $$;
CREATE OR REPLACE FUNCTION public.place_order(p_items jsonb,p_email text,p_shipping jsonb,p_kicked boolean,p_secret boolean) RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ SELECT public.place_order(p_items,p_email,p_shipping,p_kicked,p_secret,'{}'::jsonb) $$;
CREATE OR REPLACE FUNCTION public.refresh_order_tracking() RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ UPDATE public.orders SET status=CASE WHEN created_at<=now()-interval '3 days' THEN 'Delivered' WHEN created_at<=now()-interval '1 day' THEN 'Out with the night crew' ELSE 'Packed in the booth' END WHERE NOT is_ghost AND created_at<=now()-interval '10 minutes' AND status IS DISTINCT FROM CASE WHEN created_at<=now()-interval '3 days' THEN 'Delivered' WHEN created_at<=now()-interval '1 day' THEN 'Out with the night crew' ELSE 'Packed in the booth' END $$;
REVOKE ALL ON FUNCTION public.refresh_order_tracking() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.refresh_order_tracking() TO service_role;